-- ---------- 2. 动态数据表（表单对应物理表） ----------
CREATE TABLE IF NOT EXISTS `flow_data_17` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `processNo` varchar(64) DEFAULT NULL COMMENT '申请单号',
  `urgency` varchar(20) DEFAULT NULL COMMENT '紧急程度',
  `signOpinion` varchar(4000) DEFAULT NULL COMMENT '签字意见',
  `printCount` int DEFAULT NULL COMMENT '打印次数',
  `procStatus` varchar(20) DEFAULT NULL COMMENT '流程状态',
  `applicant` varchar(1000) DEFAULT NULL COMMENT '申请人',
  `apply_dept` varchar(1000) DEFAULT NULL COMMENT '所属部门',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `apply_date` date DEFAULT NULL COMMENT '申请日期',
  `seal_type` varchar(40) DEFAULT NULL COMMENT '用章类型',
  `file_name` varchar(200) DEFAULT NULL COMMENT '文件名称',
  `file_type` varchar(40) DEFAULT NULL COMMENT '文件类型',
  `copies` int DEFAULT NULL COMMENT '用章份数',
  `use_mode` varchar(20) DEFAULT NULL COMMENT '使用方式',
  `use_place` varchar(200) DEFAULT NULL COMMENT '用章地点',
  `return_time` datetime DEFAULT NULL COMMENT '预计归还时间',
  `receiver` varchar(200) DEFAULT NULL COMMENT '对方单位/接收方',
  `seal_reason` varchar(2000) DEFAULT NULL COMMENT '用章事由',
  `file_attach` varchar(2000) DEFAULT NULL COMMENT '附件（文件定稿）',
  `actual_date` date DEFAULT NULL COMMENT '实际盖章日期',
  `ledger_no` varchar(64) DEFAULT NULL COMMENT '用章台账编号',
  `process_instance_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`(191)),
  KEY `idx_urgency` (`urgency`),
  KEY `idx_process_no` (`processNo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用印申请流程数据';

CREATE TABLE IF NOT EXISTS `flow_data_bus_use_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `processNo` varchar(64) DEFAULT NULL COMMENT '流程编号',
  `urgency` varchar(20) DEFAULT NULL COMMENT '紧急程度',
  `signOpinion` varchar(4000) DEFAULT NULL COMMENT '签字意见',
  `printCount` int DEFAULT NULL COMMENT '打印次数',
  `procStatus` varchar(20) DEFAULT NULL COMMENT '流程状态',
  `applicant` varchar(1000) DEFAULT NULL COMMENT '申请人',
  `apply_dept` varchar(1000) DEFAULT NULL COMMENT '申请部门',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `use_reason` varchar(2000) DEFAULT NULL COMMENT '用车事由',
  `use_type` varchar(40) DEFAULT NULL COMMENT '用车类型',
  `depart_time` datetime DEFAULT NULL COMMENT '出发时间',
  `return_time` datetime DEFAULT NULL COMMENT '返回时间',
  `use_days` decimal(18,1) DEFAULT NULL COMMENT '用车天数',
  `passenger_count` int DEFAULT NULL COMMENT '乘车人数',
  `destination` varchar(500) DEFAULT NULL COMMENT '目的地/路线',
  `need_driver` varchar(20) DEFAULT NULL COMMENT '是否需驾驶员',
  `need_toll_card` varchar(20) DEFAULT NULL COMMENT '是否需通行费/加油卡',
  `companions` varchar(500) DEFAULT NULL COMMENT '随行人员',
  `assigned_vehicle` varchar(100) DEFAULT NULL COMMENT '指派车辆',
  `assigned_driver` varchar(1000) DEFAULT NULL COMMENT '指派驾驶员',
  `depart_mileage` decimal(18,1) DEFAULT NULL COMMENT '出车里程',
  `return_mileage` decimal(18,1) DEFAULT NULL COMMENT '回车里程',
  `actual_cost` decimal(18,2) DEFAULT NULL COMMENT '实际用车费用',
  `process_instance_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`(191)),
  KEY `idx_urgency` (`urgency`),
  KEY `idx_process_no` (`processNo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公车使用申请流程数据';

